select month(start_date) as start_month, max(monthly_fee) - min(monthly_fee) as monthly_fee_range, sum(case when status = 'CANCELLED' then monthly_fee else 0 end) as cancelled_monthly_fee, count(distinct monthly_fee) as unique_plans from subscriptions where monthly_fee between 150 and 240 group by month(start_date) order by monthly_fee_range, cancelled_monthly_fee desc, start_month limit 5;
